<?php
/** چارت سازمانی: واحدها، پست‌ها، انتساب و انتقال کارمندان با تاریخچه (PAY-02). */
namespace Agah\Erp\Http;
use Agah\Erp\Core\{Ctx,Db,Jalali,Money,Request};
use Agah\Erp\Modules\Payroll\HrService;
if(!defined('ABSPATH'))exit;
$edit=Ctx::can('payroll.edit');$units=HrService::units($cid);$posts=HrService::posts($cid);
$unitEditId=$edit?Request::int('get','unit_edit'):0;$postEditId=$edit?Request::int('get','post_edit'):0;
$unitEdit=null;foreach($units as $row)if((int)$row['id']===$unitEditId)$unitEdit=$row;
$postEdit=null;foreach($posts as $row)if((int)$row['id']===$postEditId)$postEdit=$row;
$unitOpts=[0=>'— بدون واحد بالادست —'];foreach($units as $u)$unitOpts[$u['id']]=$u['code'].' — '.$u['name'];
$postOpts=[0=>'— بدون سرپرست —'];foreach($posts as $p2)$postOpts[$p2['id']]=$p2['title'].' ('.$p2['unit_name'].')';
?>
<section class="erp-card"><h2>چارت سازمانی و پرسنل</h2><p class="muted">انتقال کارمند به پست تازه، انتساب قبلی را با تاریخ روز قبل می‌بندد؛ سابقه حذف نمی‌شود. پروندهٔ هر کارمند از فهرست «کارکنان» باز می‌شود.</p>
<h3>واحدها</h3><table class="erp-table"><thead><tr><th>کد</th><th>نام</th><th>واحد بالادست</th><th>وضعیت</th><th></th></tr></thead><tbody><?php foreach($units as $u): ?><tr><td><?php echo esc_html($u['code']); ?></td><td><?php echo esc_html($u['name']); ?></td><td><?php echo esc_html((string)$u['parent_name']); ?></td><td><?php echo $u['is_active']?'فعال':'غیرفعال'; ?></td><td><?php if($edit): ?><a class="btn btn-outline btn-sm" href="<?php echo esc_url(add_query_arg(['unit_edit'=>$u['id'],'post_edit'=>false])); ?>">ویرایش</a> <form method="post" class="erp-inline-form"><?php self::form('module_hr_unit_delete',$cid,'hr_org',$u['id']); ?><button type="submit" class="btn btn-outline btn-sm" data-confirm="واحد حذف شود؟ (فقط اگر زیرمجموعه و پست نداشته باشد)">حذف</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table>
<?php if($edit): $unitParentOpts=$unitOpts;if($unitEdit)unset($unitParentOpts[$unitEditId]); ?><form method="post" class="erp-form"><?php self::form('module_hr_unit_save',$cid,'hr_org',$unitEditId); self::input('code','کد واحد',$unitEdit['code']??'','text','required maxlength="30" dir="ltr"'); self::input('title','نام واحد',$unitEdit['name']??'','text','required maxlength="190"'); self::select('parent_id','واحد بالادست',$unitParentOpts,$unitEdit['parent_id']??0); ?><label><input type="checkbox" name="is_active" value="1" <?php checked((int)($unitEdit['is_active']??1),1); ?>> فعال</label><button type="submit" class="btn btn-primary"><?php echo $unitEdit?'ذخیرهٔ ویرایش واحد':'افزودن واحد'; ?></button><?php if($unitEdit): ?> <a class="btn btn-outline" href="<?php echo esc_url(remove_query_arg('unit_edit')); ?>">انصراف</a><?php endif; ?></form><?php endif; ?>
<h3>پست‌ها</h3><table class="erp-table"><thead><tr><th>کد</th><th>عنوان</th><th>واحد</th><th>سرپرست</th><th>متصدی فعلی</th><th></th></tr></thead><tbody><?php foreach($posts as $p2): ?><tr><td><?php echo esc_html($p2['code']); ?></td><td><?php echo esc_html($p2['title']); ?></td><td><?php echo esc_html($p2['unit_name']); ?></td><td><?php echo esc_html((string)$p2['supervisor_title']); ?></td><td><?php echo esc_html((string)$p2['holder']?:'—'); ?></td><td><?php if($edit): ?><a class="btn btn-outline btn-sm" href="<?php echo esc_url(add_query_arg(['post_edit'=>$p2['id'],'unit_edit'=>false])); ?>">ویرایش</a> <form method="post" class="erp-inline-form"><?php self::form('module_hr_post_delete',$cid,'hr_org',$p2['id']); ?><button type="submit" class="btn btn-outline btn-sm" data-confirm="پست حذف شود؟ (فقط اگر سابقهٔ انتساب نداشته باشد)">حذف</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table>
<?php if($edit&&$units): $supervisorOpts=$postOpts;if($postEdit)unset($supervisorOpts[$postEditId]); ?><form method="post" class="erp-form"><?php self::form('module_hr_post_save',$cid,'hr_org',$postEditId); self::input('code','کد پست',$postEdit['code']??'','text','required maxlength="30" dir="ltr"'); self::input('title','عنوان پست',$postEdit['title']??'','text','required maxlength="190"'); self::select('unit_id','واحد',array_slice($unitOpts,1,null,true),$postEdit['unit_id']??0); self::select('supervisor_post_id','پست سرپرست',$supervisorOpts,$postEdit['supervisor_post_id']??0); ?><label><input type="checkbox" name="is_active" value="1" <?php checked((int)($postEdit['is_active']??1),1); ?>> فعال</label><button type="submit" class="btn btn-primary"><?php echo $postEdit?'ذخیرهٔ ویرایش پست':'افزودن پست'; ?></button><?php if($postEdit): ?> <a class="btn btn-outline" href="<?php echo esc_url(remove_query_arg('post_edit')); ?>">انصراف</a><?php endif; ?></form><?php endif; ?>
<h3>انتساب و انتقال</h3>
<?php if($edit&&$posts): ?><form method="post" class="erp-form"><?php self::form('module_hr_assign',$cid,'hr_org'); self::select('employee_id','کارمند',OperationsController::employees($cid),0); self::select('post_id','پست',array_slice($postOpts,1,null,true),0); self::input('start_date','از تاریخ',Jalali::format(Jalali::today(),false),'text','required data-jalali maxlength="10"'); self::input('note','یادداشت (حکم، ارتقا …)','','text','maxlength="300"'); ?><button type="submit" class="btn btn-primary">ثبت انتساب / انتقال</button></form><?php endif; ?>
<table class="erp-table"><thead><tr><th>کارمند</th><th>پست</th><th>واحد</th><th>از</th><th>تا</th><th>یادداشت</th></tr></thead><tbody><?php foreach(HrService::assignments($cid) as $a): ?><tr><td><?php echo esc_html($a['employee_name']); ?></td><td><?php echo esc_html($a['post_title']); ?></td><td><?php echo esc_html($a['unit_name']); ?></td><td><?php echo esc_html(Jalali::format($a['start_date'])); ?></td><td><?php echo esc_html($a['end_date']?Jalali::format($a['end_date']):'جاری'); ?></td><td><?php echo esc_html($a['note']); ?></td></tr><?php endforeach; ?></tbody></table>
</section>
